    onReceived:async view=>{applyDossier(view);await refreshList();}});
  const pipelinePanel = createUnstructuredPipelinesPanel({root:$('view-pipelines'),tab:$('pipelines-tab'),api,task,notify,
    getDossier:()=>state.dossier,isBusy:()=>state.busy,
    onReceived:async view=>{applyDossier(view);await refreshList();}});
  document.querySelectorAll('.dialog-close').forEach(button => button.addEventListener('click', () => {
    if (!state.busy) button.closest('dialog').close();
  }));
  document.querySelectorAll('dialog').forEach(dialog => dialog.addEventListener('cancel', event => { if (state.busy) event.preventDefault(); }));
  document.querySelectorAll('[data-tab]').forEach(button => button.addEventListener('click', () => showTab(button.dataset.tab)));
  $('new-dossier').addEventListener('click', () => showDossier());
  $('empty-create').addEventListener('click', () => showDossier());
  $('edit-dossier').addEventListener('click', () => showDossier(true));
  $('dossier-search').addEventListener('input', renderList);
  $('refresh').addEventListener('click', () => task(async () => {
    await refreshList();
    if (state.dossier) {state.dossier = await api(endpoint()); render();}
    notify('Saved dossiers and current source availability refreshed.');
  }));
  ['source-search', 'question-filter', 'source-sort', 'selected-only'].forEach(id => {
    $(id).addEventListener(id === 'source-search' ? 'input' : 'change', () => {state.page = 0; renderSources();});
  });
  $('page-prev').addEventListener('click', () => {if (!state.busy && state.page > 0) {state.page--; renderSources();}});
  $('page-next').addEventListener('click', () => {if (!state.busy) {state.page++; renderSources();}});
  $('detail-close').addEventListener('click', () => {state.sourceId = null; renderSources();});
  $('detail-variant').addEventListener('change', () => {
    const source = sourceById(state.sourceId);
    if (!source) return;
    state.variantDigest = $('detail-variant').value;
    renderExcerpt(source, asArray(source.variants).find(variant => variant.contentDigest === state.variantDigest));
  });
  $('detail-note').addEventListener('input', () => {
    if (state.sourceId) {
      const value = $('detail-note').value, source = sourceById(state.sourceId), key = draftKey(state.sourceId);
      state.noteEditVersions.set(key, (state.noteEditVersions.get(key) || 0) + 1);
      // While a save is pending, reverting to the earlier saved text is still a new edit.
      if (!state.busy && value === (source?.note || '')) state.noteDrafts.delete(key);
      else state.noteDrafts.set(key, value);
    }
    renderNoteState();
  });
  $('save-note').addEventListener('click', () => task(() => saveEvidence()));
  $('detail-selected').addEventListener('change', () => task(() => saveEvidence()));
  $('detail-classification').addEventListener('change', () => task(() => saveEvidence()));
  ['import-results', 'sources-add'].forEach(id => $(id).addEventListener('click', () => showImport()));
  ['add-question', 'questions-add'].forEach(id => $(id).addEventListener('click', () => showQuestion()));
  ['add-finding', 'findings-add'].forEach(id => $(id).addEventListener('click', () => showFinding()));
  $('dossier-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const payload = {title: $('form-title').value.trim(), description: $('form-description').value};
      const view = state.editingDossier ? await mutate('', payload) : await api('/api/dossiers', {method: 'POST', body: payload});
      applyDossier(view); await refreshList(); $('dossier-dialog').close();
      notify(state.editingDossier ? 'Dossier details saved.' : 'Dossier created. Add the first research question.');
    }, form);
  });
  $('question-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const payload = {text: $('form-question').value.trim()};
      if (state.editingQuestion) Object.assign(payload, {notes: $('form-question-notes').value, status: $('form-question-status').value});
      await mutate('/questions' + (state.editingQuestion ? '/' + encodeURIComponent(state.editingQuestion) : ''), payload);
      $('question-dialog').close(); notify(state.editingQuestion ? 'Question and research notes saved.' : 'Research question added.');
    }, form);
  });
  $('import-form').querySelectorAll('[name=importMode]').forEach(input => input.addEventListener('change', () => {
    updateImportMode();
    if (input.value === 'openalex') task(loadSavedCohorts, $('import-form'));
  }));
  $('import-openalex-edition').addEventListener('change', renderSavedCohort);
  $('import-openalex-refresh').addEventListener('click', () => task(loadSavedCohorts, $('import-form')));
  $('import-retained-provider').addEventListener('change', () => {
    $('import-format-help').textContent = $('import-retained-provider').value === 'openalex' ?
      'Import the original OpenAlex response containing meta and results.' :
      'Research envelopes retain their source terms and original result entries.';
  });
  $('import-files').addEventListener('change', () => {
    state.importCompleted.clear();
    $('import-file-list').replaceChildren(...Array.from($('import-files').files || []).map(file => {
      const row = node('div'); row.append(node('span', file.name), node('span', (file.size / 1024).toFixed(1) + ' KiB')); return row;
    }));
  });
  $('import-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const questionId = $('import-question').value, label = $('import-label').value.trim();
      if (form.elements.importMode.value === 'openalex') {
        const editionId = $('import-openalex-edition').value;
        if (!editionId) throw new Error('OPENALEX_SAVED_EDITION_REQUIRED');
        const imported = await api(endpoint('/openalex'), {method:'POST', body:{questionId,editionId,
          ...(label ? {label} : {}),expectedRevision:state.dossier.revision}});
        state.dossier = imported.dossier;
        await refreshList(); render();
        $('import-dialog').close();
        notify('Saved cohort imported: ' + imported.importedPages + ' new pages, ' + imported.reusedPages +
          ' retained pages · source coverage ' + imported.coverage.state + '.');
      } else if (form.elements.importMode.value === 'reference') {
        const reference = parseJson($('import-reference').value);
        await mutate('/reference', {questionId, label, provider: $('import-provider').value.trim(), reference});
        $('import-dialog').close(); notify('Provider edition attached to the research question.');
      } else {
        const files = Array.from($('import-files').files || []);
        if (!files.length) throw new Error('RESULT_FILE_REQUIRED');
        let completed = state.importCompleted.size;
        for (let index = 0; index < files.length; index++) {
          if (state.importCompleted.has(index)) continue;
          const file = files[index];
          const rawText = await readOriginalFile(file);
          try {
            await mutate('/receive', {questionId, label: label ? label + (files.length > 1 ? ' · ' + file.name : '') : file.name,
              provider: $('import-retained-provider').value, filename: file.name, rawText});
            state.importCompleted.add(index); completed++; notify('Imported ' + completed + ' of ' + files.length + ' files.');
          } catch (error) {
            error.detail = 'Imported ' + completed + ' of ' + files.length + ' files. ' + file.name + ': ' + errorMessage(error);
            throw error;
          }
        }
        $('import-dialog').close(); notify(completed + ' result edition' + (completed === 1 ? '' : 's') + ' imported.');
      }
    }, form);
  });
  $('finding-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const sourceIds = Array.from(form.querySelectorAll('[name=findingSource]:checked')).map(input => input.value);
      const payload = {title: $('finding-title').value.trim(), text: $('finding-text').value};
      if (state.editingFinding) {
        if ($('replace-finding-sources').checked) payload.sourceIds = sourceIds;
        await mutate('/findings/' + encodeURIComponent(state.editingFinding.id), payload);
      } else await mutate('/findings', {...payload, questionId: $('finding-question').value, sourceIds});
      $('finding-dialog').close(); showTab('findings'); notify('Finding and source references saved.');
    }, form);
  });
  $('finding-question').addEventListener('change', renderFindingSources);
  $('replace-finding-sources').addEventListener('change', () => {
    $('preserve-finding-sources').textContent = $('replace-finding-sources').checked ? 'The new selection replaces the original source references.' : 'Current source references are kept when you edit the analysis.';
    $('finding-form').querySelectorAll('[name=findingSource]').forEach(input => {input.disabled = !$('replace-finding-sources').checked;});
  });
  $('selection-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      await mutate('/selections', {occurrenceId: state.editingSelection.occurrenceId,
        selected: $('selection-selected').checked, note: $('selection-note').value,
        classification: $('selection-classification').value});
      $('selection-dialog').close(); notify('Saved source analysis updated.');
    }, form);
  });
  $('compare-form').addEventListener('submit', event => {
    event.preventDefault();
    task(async () => {
      const before = $('compare-before').value, after = $('compare-after').value;
      if (!before || !after || before === after) throw Object.assign(new Error('DISTINCT_REVISIONS_REQUIRED'), {detail: 'Choose two different revisions.'});
      renderComparison(await api(endpoint('/compare?before=' + encodeURIComponent(before) + '&after=' + encodeURIComponent(after))));
    });
  });
  $('export-open').addEventListener('click', () => {
    if (!state.busy) {clearFormError($('export-form')); $('export-dialog').showModal();}
  });
  $('export-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const format = $('export-format').value, response = await api(endpoint('/export?format=' + format), {download: true});
      const blob = await response.blob(), url = URL.createObjectURL(blob), anchor = document.createElement('a');
      const header = response.headers.get('Content-Disposition') || '';
      const match = header.match(/filename="([^"]+)"/);
      anchor.href = url; anchor.download = match?.[1] || 'research-dossier.' + format;
      document.body.append(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(url), 30000);
      $('export-dialog').close(); notify('Dossier export downloaded.');
    }, form);
  });
  ['open-portable', 'empty-open'].forEach(id => $(id).addEventListener('click', () => {if (!state.busy) {$('portable-file').value = ''; $('portable-file').click();}}));
  $('portable-file').addEventListener('change', () => task(async () => {
    const file = $('portable-file').files?.[0]; if (!file) return;
    if (file.size > MAX_PORTABLE_FILE_BYTES)
      throw Object.assign(new Error('FILE_TOO_LARGE'), {detail: 'Choose a portable JSON or gzip file up to 256 MiB.'});
    notify('Opening the dossier and its retained sources…');
    const view = await api('/api/reopen-stream', {method: 'POST', file});
    applyDossier(view); await refreshList(); notify('Portable dossier reopened.');
  }));
  $('session-form').addEventListener('submit', event => {
    event.preventDefault(); const form = event.currentTarget;
    task(async () => {
      const supplied = new URL($('session-url').value);
      if (supplied.origin !== location.origin) throw Object.assign(new Error('WORKSPACE_ADDRESS_MISMATCH'), {detail: 'Use the complete address printed by this workspace instance.'});
      const token = new URLSearchParams(supplied.hash.slice(1)).get('token');
      if (!token || !/^[a-f0-9]{64}$/.test(token)) throw new Error('SESSION_FRAGMENT_REQUIRED');
      state.token = token; safeStorage.set(token); await refreshList(); $('session-dialog').close();
      $('session-url').value = ''; notify('Local workspace session opened.');
    }, form);
  });
  window.addEventListener('beforeunload', event => {
    if (state.noteDrafts.size > 0) {event.preventDefault(); event.returnValue = '';}
  });
  async function start() {
    const params = new URLSearchParams(location.hash.slice(1));
    state.token = params.get('token') || safeStorage.get();
    if (state.token) safeStorage.set(state.token);
    params.delete('token');
    history.replaceState(null, '', params.toString() ? '#' + params.toString() : location.pathname);
    if (!state.token) {$('connection').textContent = 'Session needed'; $('session-dialog').showModal(); return;}
    await task(async () => {
      await refreshList();
      const requested = params.get('dossier');
      if (requested && state.dossiers.some(item => item.id === requested)) await openDossier(requested);
      else if (state.dossiers.length) await openDossier(state.dossiers[0].id);
      else render();
    });
  }
  start();
})();

// MIT. Crossref review controls use the original research workspace's session and dossier state.
export function createCrossrefPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  const local={configured:false,identity:null,dossierId:null,revision:null,shown:false,current:null,items:[],
    next:null,page:0,poll:null,loading:false,loadVersion:0,pending:null};
  root.innerHTML=`
    <div class="view-heading"><div><h2>DOI metadata</h2><p class="muted">Review publication metadata and registered updates for the evidence in a saved question.</p></div><button type="button" id="crossref-refresh">Refresh operations</button></div>
    <p id="crossref-account" class="muted small"></p>
    <form id="crossref-plan-form" class="crossref-form">
      <label>Research question<select id="crossref-question" required></select></label>
      <label>Edition label<input id="crossref-label" maxlength="200" value="Crossref DOI enrichment" required></label>
      <div class="crossref-options">
        <label><input type="checkbox" id="crossref-selected" checked>Selected evidence only</label>
        <label><input type="checkbox" id="crossref-updates" checked>Include registered updates</label>
        <label><input type="checkbox" id="crossref-fresh">Refresh provider responses</label>
      </div>
      <p class="muted small">The review records the exact DOI scope. Existing response captures are reused unless you request a refresh. Acquisition progress remains saved when this window closes.</p>
      <div class="crossref-form-footer"><p id="crossref-scope" class="muted small"></p><button type="submit" class="primary" id="crossref-prepare">Review acquisition</button></div>
      <p class="form-error" hidden></p>
    </form>
    <div class="crossref-layout">
      <section class="crossref-history" aria-label="Saved Crossref operations"><h3>Saved operations</h3><div id="crossref-operation-list"></div><button type="button" id="crossref-more" hidden>More operations</button></section>
      <section class="crossref-review" aria-label="Crossref operation review">
        <p id="crossref-empty" class="muted">Choose a saved operation or review a new acquisition.</p>
        <div id="crossref-review-content" hidden>
          <div class="crossref-review-heading"><div><h3 id="crossref-plan-title"></h3><p id="crossref-plan-state" role="status"></p></div><span class="tag" id="crossref-coverage"></span></div>
          <p id="crossref-plan-question"></p><p id="crossref-plan-meta" class="muted small"></p>
          <details class="original-record"><summary>Reviewed DOI scope</summary><pre id="crossref-dois"></pre></details>
          <div id="crossref-progress" class="provider-outcome" role="status"></div>
          <p id="crossref-problem" class="form-error" role="alert" hidden></p>
          <div class="button-row crossref-actions">
            <button type="button" class="primary" id="crossref-start">Acquire metadata</button>
            <button type="button" id="crossref-stop" hidden>Stop acquisition</button>
            <button type="button" class="primary" id="crossref-receive" hidden>Retain reviewed edition</button>
            <button type="button" id="crossref-download" hidden>Download original edition</button>
          </div>
          <div id="crossref-result" hidden>
            <h3>Received metadata</h3><p id="crossref-result-summary" class="muted small"></p>
            <div class="table-wrap"><table><thead><tr><th>Publication</th><th>Publication dates</th><th>Review</th></tr></thead><tbody id="crossref-records"></tbody></table></div>
            <div class="pagination"><button type="button" id="crossref-prev" class="quiet compact">Previous</button><span id="crossref-page"></span><button type="button" id="crossref-next" class="quiet compact">Next</button></div>
            <section id="crossref-record-detail" class="crossref-record-detail" hidden></section>
            <details class="original-record"><summary>Acquisition coverage and provider responses</summary><pre id="crossref-usage"></pre></details>
          </div>
        </div>
      </section>
    </div>`;
  const $=id=>root.querySelector('#'+id),nodes={};
  for(const element of root.querySelectorAll('[id]'))nodes[element.id]=element;
  const el=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(className)node.className=className;return node;};
  const array=value=>Array.isArray(value)?value:[];
  const stringify=value=>JSON.stringify(value,null,2);
  const endpoint=(suffix='',id=local.dossierId)=>'/api/dossiers/'+encodeURIComponent(id)+'/crossref'+suffix;
  const operationPath=(suffix='',current=local.current)=>endpoint('/operations/'+current.plan.id+suffix,current.plan.request.dossierId);
  const friendly=code=>String(code||'Operation failed').toLowerCase().replaceAll('_',' ');
  const date=value=>value?new Date(value).toLocaleString():'';
  const dateParts=value=>array(value?.['date-parts']).map(parts=>parts.join('-')).join('; ')||value?.['date-time']||'Not supplied';
  function stopPoll(){if(local.poll!==null)clearTimeout(local.poll);local.poll=null;}
  function schedule(){
    stopPoll();
    if(!local.shown||!local.current?.running)return;
    local.poll=setTimeout(()=>loadCurrent().catch(error=>problem(error.message)),1500);
  }
  function problem(message){$('crossref-problem').textContent=message;$('crossref-problem').hidden=!message;}
  function withAction(work,form=null){
    return task(async()=>{try{await work();}catch(error){
      if(error.code==='REVISION_CONFLICT'&&local.current)await loadCurrent().catch(()=>{});
      throw error;
    }finally{renderCurrent();renderScope();}},form);
  }
  function pendingKey(){return 'crossref-prepared-request:'+location.origin+':'+local.dossierId;}
  function restorePending(){try{local.pending=JSON.parse(sessionStorage.getItem(pendingKey())||'null');}catch{local.pending=null;}}
  function savePending(value){local.pending=value;try{if(value)sessionStorage.setItem(pendingKey(),JSON.stringify(value));else sessionStorage.removeItem(pendingKey());}catch{}}
  function scope(){
    const view=getDossier(),questionId=$('crossref-question').value,selectedOnly=$('crossref-selected').checked;
    return array(view?.sources).filter(source=>source.doi&&(!selectedOnly||source.selected)&&
      array(source.citations).some(citation=>citation.questionId===questionId));
  }
  function renderScope(){
    const count=new Set(scope().map(source=>String(source.doi).toLowerCase())).size;
    $('crossref-scope').textContent=count+' DOI source'+(count===1?'':'s')+' in the current question selection.';
    $('crossref-prepare').disabled=!local.configured||count===0||isBusy();
  }
  function renderQuestions(){
    const view=getDossier(),previous=$('crossref-question').value;
    $('crossref-question').replaceChildren(...array(view?.questions).map(question=>{const option=el('option',question.text);option.value=question.id;return option;}));
    if(array(view?.questions).some(question=>question.id===previous))$('crossref-question').value=previous;
    renderScope();
  }
  function renderList(){
    $('crossref-operation-list').replaceChildren(...local.items.map(item=>{
      const button=el('button',undefined,'crossref-operation'+(item.plan.id===local.current?.plan.id?' active':''));
      button.type='button';button.append(el('strong',item.plan.request.label),el('span',item.operation.phase+' · '+item.plan.payload.dois.length+' DOIs'),
        el('span',date(item.plan.preparedAt)));
      button.addEventListener('click',()=>withAction(async()=>{local.current=item;local.page=0;await loadCurrent();renderList();}));
      return button;
    }));
    if(!local.items.length)$('crossref-operation-list').append(el('p','Prepared scopes and results appear here.','muted small'));
    $('crossref-more').hidden=!local.next;
  }
  async function loadList({more=false}={}){
    const id=local.dossierId,version=local.loadVersion;if(!id||!local.configured)return;
    const data=await api(endpoint('/operations?limit=30'+(more&&local.next?'&after='+encodeURIComponent(local.next):''),id));
    if(version!==local.loadVersion||id!==local.dossierId)return;
    local.items=more?[...local.items,...data.items]:data.items;local.next=data.next;
    renderList();
  }
  async function loadCurrent(){
    if(!local.current||local.loading)return;
    const id=local.current.plan.id,dossierId=local.dossierId,version=local.loadVersion;local.loading=true;
    try{
      const value=await api(operationPath());
      if(version!==local.loadVersion||dossierId!==local.dossierId||id!==local.current?.plan.id)return;
      local.current=value;
      const index=local.items.findIndex(item=>item.plan.id===id);
      if(index>=0)local.items[index]={plan:value.plan,operation:value.operation};else local.items.unshift({plan:value.plan,operation:value.operation});
      renderCurrent();renderList();
    }finally{local.loading=false;schedule();}
  }
  async function refresh(){
    if(!local.configured||!local.dossierId)return;
    await loadList();
    if(local.current)await loadCurrent();
  }
  function fieldComparison(doi){
    const comparison=local.current?.review?.comparison;
    if(!comparison)return {label:'Retained record',fields:[]};
    const changed=array(comparison.changed).find(row=>row.doi===doi);
    if(changed)return {label:changed.fields.length+' changed field'+(changed.fields.length===1?'':'s'),fields:changed.fields};
    if(array(comparison.added).some(row=>row.doi===doi))return {label:'First Crossref metadata',fields:[]};
    return {label:'No saved Crossref field changes',fields:[]};
  }
  function displayRecord(record){
    const target=$('crossref-record-detail');target.hidden=false;target.replaceChildren(el('h3',record.title));
    const link=el('a',record.doi);link.href='https://doi.org/'+encodeURIComponent(record.doi);link.target='_blank';link.rel='noopener noreferrer';target.append(link);
    target.append(el('p',array(record.authors).join('; '),'muted small'));
    const table=el('table'),body=el('tbody');
    for(const [label,value] of Object.entries(record.dates||{})){const row=el('tr');row.append(el('th',label),el('td',dateParts(value)));body.append(row);}
    table.append(body);target.append(table);
    const comparison=fieldComparison(record.doi);
    target.append(el('h3',comparison.label));
    for(const field of comparison.fields){
      const details=el('details',undefined,'original-record');details.append(el('summary',field.field??field.key??'Changed field'));
      const pre=el('pre',stringify(field));details.append(pre);target.append(details);
    }
    for(const [title,value] of [['Funders',record.funders],['Licences',record.licenses],['Registered relations',record.relations],['Original source occurrences',record.sourceOccurrences]]){
      const details=el('details',undefined,'original-record');details.append(el('summary',title),el('pre',stringify(value)));target.append(details);
    }
    target.append(el('p','Deposited reference count: '+(record.referenceCount??'Not supplied'),'muted small'));
    target.scrollIntoView({block:'nearest'});
  }
  function renderRecords(){
    const records=array(local.current?.review?.records),pages=Math.max(1,Math.ceil(records.length/20));
    local.page=Math.min(local.page,pages-1);
    $('crossref-records').replaceChildren(...records.slice(local.page*20,local.page*20+20).map(record=>{
      const row=el('tr'),publication=el('td'),button=el('button',record.title,'source-title');
      button.type='button';button.addEventListener('click',()=>displayRecord(record));
      publication.append(button,el('p',record.doi,'muted small'));
      const dates=el('td');
      for(const name of ['published-online','published-print','issued'])if(record.dates?.[name])dates.append(el('div',name.replace('published-','')+': '+dateParts(record.dates[name])));
      row.append(publication,dates,el('td',fieldComparison(record.doi).label));return row;
    }));
    $('crossref-page').textContent=records.length+' records · Page '+(local.page+1)+' of '+pages;
    $('crossref-prev').disabled=local.page===0||isBusy();$('crossref-next').disabled=local.page+1===pages||isBusy();
  }
  function renderCurrent(){
    const value=local.current;$('crossref-empty').hidden=!!value;$('crossref-review-content').hidden=!value;
    if(!value)return;
    const {plan,operation}=value,review=value.review;
    $('crossref-plan-title').textContent=plan.request.label;
    $('crossref-plan-state').textContent=value.interrupted?'Interrupted — retained responses are ready to resume':operation.phase==='IMPORTED'?'Retained in dossier revision '+operation.received.revision:operation.phase;
    $('crossref-plan-question').textContent=plan.payload.question;
    $('crossref-plan-meta').textContent='Reviewed from revision '+plan.request.expectedRevision+' · '+date(plan.preparedAt)+
      ' · '+plan.payload.metadataRequests+' metadata requests'+(plan.request.includeUpdates?' and at least '+plan.payload.minimumUpdateRequests+' update requests':'')+
      ' · '+(plan.request.refresh?'Fresh provider responses':'Retained response cache enabled');
    $('crossref-dois').textContent=plan.payload.dois.join('\n');
    $('crossref-coverage').textContent=review?.coverage??'Awaiting acquisition';
    $('crossref-progress').textContent=operation.responses+' original response'+(operation.responses===1?'':'s')+' retained.'+
      (operation.lastCapture?' Latest: HTTP '+operation.lastCapture.status+' · '+operation.lastCapture.url:'')+
      (operation.received?' Edition received at '+date(operation.received.receivedAt)+'.':'');
    const warnings=[];
    if(operation.error)warnings.push(friendly(operation.error)+'.');
    if(value.sourceMatches===false)warnings.push('This operation was prepared for a different source configuration. Its retained edition remains available; create a new scope to acquire through the current configuration.');
    if(value.questionMatches===false)warnings.push('The saved question has changed. Review a new acquisition scope for that question.');
    if(review?.warnings?.length)warnings.push(...review.warnings.map(row=>friendly(row.code)+(row.dois?.length?' ('+row.dois.join(', ')+')':'')+'.'));
    problem(warnings.join(' '));
    const canStart=['PREPARED','STOPPED','FAILED'].includes(operation.phase)||value.interrupted;
    $('crossref-start').hidden=!canStart;$('crossref-start').disabled=value.sourceMatches===false||isBusy();
    $('crossref-start').textContent=operation.responses?'Resume acquisition':'Acquire metadata';
    $('crossref-stop').hidden=!value.running;$('crossref-stop').disabled=isBusy();
    $('crossref-receive').hidden=operation.phase!=='READY';
    $('crossref-receive').disabled=value.questionMatches!==true||isBusy();
    $('crossref-receive').textContent=review?.records?.length?'Retain reviewed edition':'Retain provider outcome';
    $('crossref-download').hidden=!['READY','IMPORTED'].includes(operation.phase);$('crossref-download').disabled=isBusy();
    $('crossref-result').hidden=!review;
    if(review){
      $('crossref-result-summary').textContent=review.records.length+' metadata records; '+array(review.usage.updates).length+' update collections. The comparison uses saved dossier revision '+value.currentRevision+'.';
      $('crossref-usage').textContent=stringify({coverage:review.coverage,usage:review.usage,warnings:review.warnings});
      renderRecords();
    }
    schedule();
  }
  $('crossref-plan-form').addEventListener('submit',event=>{
    event.preventDefault();withAction(async()=>{
      const view=getDossier();
      const input={questionId:$('crossref-question').value,expectedRevision:view.revision,selectedOnly:$('crossref-selected').checked,
        includeUpdates:$('crossref-updates').checked,refresh:$('crossref-fresh').checked,label:$('crossref-label').value};
      if(!local.pending||stringify(local.pending.input)!==stringify(input))savePending({requestId:crypto.randomUUID(),input});
      const result=await api(endpoint('/prepare'),{method:'POST',body:{...local.pending.input,requestId:local.pending.requestId}});
      local.current=result;local.page=0;savePending(null);$('crossref-record-detail').hidden=true;
      await loadList();await loadCurrent();notify('Review the saved DOI scope before starting acquisition.');
    },event.currentTarget);
  });
  for(const id of ['crossref-question','crossref-selected'])$(id).addEventListener('change',renderScope);
  $('crossref-refresh').addEventListener('click',()=>withAction(refresh));
  $('crossref-more').addEventListener('click',()=>withAction(()=>loadList({more:true})));
  $('crossref-start').addEventListener('click',()=>withAction(async()=>{
    local.current=await api(operationPath('/start'),{method:'POST',body:{expectedPlanSha256:local.current.plan.sha256}});
    await loadCurrent();notify('Crossref acquisition is running. Its original responses and progress are retained.');
  }));
  $('crossref-stop').addEventListener('click',()=>withAction(async()=>{
    local.current=await api(operationPath('/stop'),{method:'POST',body:{}});await loadCurrent();
    notify('Acquisition stopped. Resume this saved operation to reuse its original responses.');
  }));
  $('crossref-receive').addEventListener('click',()=>withAction(async()=>{
    const current=local.current;
    const result=await api(operationPath('/receive'),{method:'POST',body:{expectedRevision:current.currentRevision,
      expectedPlanSha256:current.plan.sha256,expectedEditionSha256:current.operation.editionSha256}});
    await onReceived(result.dossier);await loadCurrent();await loadList();
    notify('Reviewed Crossref edition retained in dossier revision '+result.receipt.revision+'.');
  }));
  $('crossref-download').addEventListener('click',()=>withAction(async()=>{
    const response=await api(operationPath('/edition'),{download:true}),blob=await response.blob(),url=URL.createObjectURL(blob);
    const link=el('a');link.href=url;link.download=local.current.plan.id+'.crossref.json';document.body.append(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
  }));
  $('crossref-prev').addEventListener('click',()=>{if(local.page>0){local.page--;renderRecords();}});
  $('crossref-next').addEventListener('click',()=>{local.page++;renderRecords();});
  window.addEventListener('beforeunload',stopPoll);
  return {
    configure(value){local.configured=value?.configured===true;local.identity=value?.identity??null;tab.hidden=!local.configured;
      $('crossref-account').textContent=local.identity?'Source account: '+local.identity.account+' · '+local.identity.mode+' provider pool':'';
      renderScope();},
    setDossier(view){
      if(view?.id!==local.dossierId){stopPoll();local.shown=false;local.dossierId=view?.id??null;local.loadVersion++;local.items=[];local.current=null;local.page=0;local.next=null;restorePending();renderList();renderCurrent();}
      local.revision=view?.revision??null;renderQuestions();
    },
    show(visible){const changed=visible!==local.shown;local.shown=visible;if(!visible)stopPoll();
      else if(changed)refresh().catch(error=>notify(friendly(error.code||error.message),'error'));else schedule();},
    updateBusy(){renderScope();renderCurrent();}
  };
}

// MIT. Original document purchase and retained-edition review in the research operator.
const element=(tag,text,className)=>{
  const value=document.createElement(tag);if(text!==undefined)value.textContent=text;
  if(className)value.className=className;return value;
};
const array=value=>Array.isArray(value)?value:[];
const pretty=value=>JSON.stringify(value,null,2);
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const bytes=value=>new Intl.NumberFormat().format(value)+' bytes';
const friendly=error=>({
  UNSTRUCTURED_RESPONSE_NOT_SAVED:'The original purchase has no completed saved document response yet. Open its existing buyer operation to inspect it.',
  UNSTRUCTURED_REVIEWED_EDITION_CHANGED:'The document edition changed. Refresh and review its current original record.',
  UNSTRUCTURED_RECEIVING_LABEL_CONFLICT:'This exact document is already received under a different label. Open that retained edition.',
  REVISION_CONFLICT:'The dossier changed after this decision was prepared. Refresh the dossier and review the receiving scope.',
})[error?.code]||error?.detail||error?.message||'The document operation could not complete.';

export function createUnstructuredPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  root.innerHTML=`
    <div class="view-heading"><div><h2>Documents</h2><p class="muted">Review the original upload, processing profile and located document elements, then retain the edition with a research question.</p></div><button type="button" id="document-refresh">Refresh documents</button></div>
    <p id="document-source" class="muted small"></p>
    <div class="document-layout">
      <section class="document-history" aria-label="Document purchases and retained editions">
        <h3>Saved purchases</h3><div id="document-purchases"></div><button type="button" id="document-more" hidden>More purchases</button>
        <h3>Retained editions</h3><div id="document-editions"></div>
      </section>
      <section class="document-review" aria-label="Document review">
        <p id="document-empty" class="muted">Choose a completed purchase or an edition already retained in this dossier.</p>
        <div id="document-current" hidden>
          <h3 id="document-title"></h3><p id="document-summary" class="muted small"></p>
          <div class="document-status"><p><strong>Payment</strong><span id="document-payment"></span></p><p><strong>Output</strong><span id="document-output"></span></p></div>
          <div class="button-row"><button type="button" data-document-download="document">Original document</button><button type="button" data-document-download="response">Provider JSON</button><button type="button" data-document-download="edition">Research edition</button></div>
          <details class="original-record"><summary>Processing profile and original record</summary><pre id="document-profile"></pre></details>
          <p id="document-warnings" class="muted small"></p>
          <form id="document-receive-form" class="document-receive-form">
            <label>Research question<select id="document-question" required></select></label>
            <label>Edition label<input id="document-label" maxlength="240" required></label>
            <div class="button-row"><button type="submit" id="document-receive" class="primary">Retain reviewed document</button><button type="button" id="document-discard-pending" hidden>Review a new receiving decision</button></div>
            <p id="document-pending" class="muted small" role="status"></p><p class="form-error" hidden></p>
          </form>
          <p id="document-retained" class="muted small" hidden></p>
          <form id="document-filter" class="document-filter">
            <label>Page<select id="document-page"><option value="">All pages</option></select></label>
            <label>Element type<select id="document-type"><option value="">All types</option></select></label>
            <label>Text contains<input id="document-query" maxlength="2000" type="search"></label>
            <button type="submit">Filter elements</button>
          </form>
          <p id="document-element-count" class="muted small" role="status"></p>
          <div id="document-elements" class="document-elements"></div>
          <div class="pagination"><button type="button" id="document-prev">Previous</button><span id="document-page-label"></span><button type="button" id="document-next">Next</button></div>
          <section id="document-element-detail" class="document-element-detail" hidden></section>
        </div>
      </section>
    </div>
  `;
  const $=id=>root.querySelector('#'+id);
  const local={id:null,shown:false,configured:false,workspaceId:null,version:0,purchases:[],editions:[],
    next:null,current:null,records:null,offset:0,pending:null};
  const endpoint=suffix=>'/api/dossiers/'+encodeURIComponent(local.id)+'/unstructured'+(suffix||'');
  const pendingKey=()=> 'unstructured-receive:'+local.id;
  function savePending(value){
    local.pending=value;
    try {value?localStorage.setItem(pendingKey(),JSON.stringify(value)):localStorage.removeItem(pendingKey());}
    catch {notify('This browser could not retain the receiving decision across a restart. Keep this page open until its result returns.','error');}
  }
  function restorePending(){
    local.pending=null;
    try{const value=JSON.parse(localStorage.getItem(pendingKey())||'null');
      if(value&&value.dossierId===local.id&&value.input?.selection?.purchaseId)local.pending=value;
    }catch{}
  }
  async function withAction(action,form){
    return task(async()=>{try{return await action();}catch(error){error.detail=friendly(error);throw error;}},form);
  }
  function renderQuestions(){
    const selected=local.pending?.input?.questionId ?? $('document-question').value,view=getDossier();
    $('document-question').replaceChildren(...array(view?.questions).map(question=>{
      const option=element('option',question.text);option.value=question.id;return option;
    }));
    if(array(view?.questions).some(question=>question.id===selected))$('document-question').value=selected;
  }
  function renderList(){
    const button=(selection,title,subtitle)=>{
      const value=element('button',undefined,'document-item'+(same(selection,local.current?.selection)?' active':''));
      value.type='button';value.append(element('strong',title),element('span',subtitle,'muted small'));
      value.addEventListener('click',()=>withAction(()=>open(selection)));return value;
    };
    $('document-purchases').replaceChildren(...local.purchases.map(row=>button({purchaseId:row.id},
      row.intentId,row.profileId+' · '+row.state+' · '+row.outputStatus)));
    if(!local.purchases.length)$('document-purchases').append(element('p',local.configured?
      'Completed purchases from the configured original buyer appear here.':'Connect an original document buyer to receive new purchases.','muted small'));
    $('document-editions').replaceChildren(...local.editions.map(row=>button({editionId:row.id},
      row.label,(row.document?.filename||'Document')+' · '+
        (row.elementCount===null?'open to review':row.elementCount+' elements'))));
    if(!local.editions.length)$('document-editions').append(element('p','Retained document editions appear here.','muted small'));
    $('document-more').hidden=!local.next;
  }
  function renderCurrent(){
    const value=local.current;$('document-empty').hidden=!!value;$('document-current').hidden=!value;
    if(!value)return;
    $('document-title').textContent=value.document.filename;
    $('document-summary').textContent=bytes(value.document.bytes)+' · '+value.summary.elements+
      ' elements · '+value.summary.pages.length+' located pages · '+value.summary.withTableHtml+' table records';
    $('document-payment').textContent=value.native.status+
      (value.native.sellerReportedSettlement?' · '+value.native.sellerReportedSettlement:'');
    $('document-output').textContent=value.native.responseStatus+' · HTTP '+value.native.httpStatus;
    $('document-profile').textContent=pretty({profile:value.binding.profileId,parameters:value.parameters,
      document:value.document,originalPurchase:value.binding,editionSha256:value.editionSha256});
    $('document-warnings').textContent=array(value.warnings).join(' ');
    const retained=!!value.retained;$('document-receive-form').hidden=retained&&!local.pending;
    $('document-retained').hidden=!retained;
    $('document-retained').textContent=retained?'Retained as '+value.retained.label+
      '. Evidence selection, notes and findings remain in this dossier.':'';
    const pending=local.pending?.input;
    if(pending){
      $('document-label').value=pending.label;
      if(array(getDossier()?.questions).some(question=>question.id===pending.questionId))$('document-question').value=pending.questionId;
    }
    const pendingQuestion=pending&&array(getDossier()?.questions).find(question=>question.id===pending.questionId);
    $('document-pending').textContent=pending?'Saved decision: '+pending.label+' → '+
      (pendingQuestion?.text||pending.questionId)+'. Original purchase '+pending.selection.purchaseId+
      ', reviewed edition '+pending.expectedEditionSha256+'. Retry recovers this exact decision.':'';
    $('document-discard-pending').hidden=!local.pending;
    $('document-receive').textContent=local.pending?'Retry saved receiving decision':'Retain reviewed document';
    $('document-question').disabled=!!local.pending||isBusy();
    $('document-label').disabled=!!local.pending||isBusy();
    $('document-receive').disabled=isBusy()||(!local.pending&&!$('document-question').value);
    $('document-prev').disabled=isBusy()||local.offset===0;
    $('document-next').disabled=isBusy()||!local.records||local.records.nextOffset===null;
  }
  function showElement(row){
    const target=$('document-element-detail'),value=row.element;target.hidden=false;
    target.replaceChildren(element('h3',(value.type??'Element')+' '+row.position),
      element('p','Original ID: '+value.element_id,'muted small'),element('pre',value.text,'document-full-text'));
    const metadata=element('details',undefined,'original-record');metadata.append(element('summary','Page, coordinates and original metadata'),
      element('pre',pretty(value.metadata)));target.append(metadata);
    if(typeof value.metadata.text_as_html==='string'){
      const table=element('details',undefined,'original-record');
      table.append(element('summary','Original table HTML'),element('pre',value.metadata.text_as_html));target.append(table);
    }
  }
  function renderRecords(){
    const value=local.records;if(!value)return;
    $('document-element-count').textContent=value.filtered+' of '+value.total+' elements match the current filters.';
    $('document-elements').replaceChildren(...value.items.map(row=>{
      const button=element('button',undefined,'document-element');button.type='button';
      button.append(element('span','#'+row.position+' · '+(row.element.type??'Element')+
        (row.element.metadata.page_number===undefined?'':' · page '+row.element.metadata.page_number),'muted small'),
        element('span',row.element.text.length>480?row.element.text.slice(0,480)+'…':row.element.text));
      button.addEventListener('click',()=>showElement(row));return button;
    }));
    if(!value.items.length)$('document-elements').append(element('p','No document elements match these filters.','muted'));
    $('document-page-label').textContent='Page '+(Math.floor(local.offset/25)+1)+' of '+Math.max(1,Math.ceil(value.filtered/25));
    renderCurrent();
  }
  async function loadElements(){
    if(!local.current)return;
    const version=local.version,selection=local.current.selection,sha=local.current.editionSha256;
    const value=await api(endpoint('/elements'),{method:'POST',body:{selection,expectedEditionSha256:sha,
      offset:local.offset,limit:25,page:$('document-page').value,type:$('document-type').value,query:$('document-query').value}});
    if(version!==local.version||!same(selection,local.current?.selection)||sha!==local.current?.editionSha256)return;
    local.records=value;renderRecords();
  }
  async function open(selection){
    const version=++local.version;
    const value=await api(endpoint('/review'),{method:'POST',body:{selection}});
    if(version!==local.version)return;
    local.current=value;local.offset=0;local.records=null;
    $('document-element-detail').hidden=true;$('document-query').value='';
    $('document-page').replaceChildren(element('option','All pages'),...value.summary.pages.map(page=>{
      const option=element('option','Page '+page);option.value=page;return option;
    }));$('document-page').options[0].value='';
    $('document-type').replaceChildren(element('option','All types'),...Object.keys(value.summary.types).map(type=>{
      const option=element('option',type);option.value=type;return option;
    }));$('document-type').options[0].value='';
    $('document-label').value=value.retained?.label||(value.document.filename+' · '+value.binding.profileId).slice(0,240);
    renderQuestions();renderList();renderCurrent();await loadElements();
  }
  async function loadList(more=false){
    if(!local.id)return;
    const version=local.version,value=await api(endpoint('')+(more&&local.next?'?after='+encodeURIComponent(local.next):''));
    if(version!==local.version)return;
    local.purchases=more?[...local.purchases,...value.purchases]:value.purchases;local.editions=value.editions;
    local.next=value.nextAfter;local.configured=value.configured;local.workspaceId=value.workspaceId;
    $('document-source').textContent=value.configured?'Original buyer workspace: '+value.workspaceId:
      'Retained documents reopen from this dossier and its portable archive.';
    renderList();renderCurrent();
  }
  async function refresh(){const version=local.version;await loadList();if(version!==local.version)return;if(local.current)await open(local.current.selection);}
  $('document-refresh').addEventListener('click',()=>withAction(refresh));
  $('document-more').addEventListener('click',()=>withAction(()=>loadList(true)));
  $('document-filter').addEventListener('submit',event=>{event.preventDefault();withAction(async()=>{
    local.offset=0;$('document-element-detail').hidden=true;await loadElements();
  });});
  $('document-prev').addEventListener('click',()=>withAction(async()=>{local.offset=Math.max(0,local.offset-25);await loadElements();}));
  $('document-next').addEventListener('click',()=>withAction(async()=>{if(Number.isSafeInteger(local.records?.nextOffset)){local.offset=local.records.nextOffset;await loadElements();}}));
  $('document-question').addEventListener('change',renderCurrent);
  $('document-receive-form').addEventListener('submit',event=>{
    event.preventDefault();withAction(async()=>{
      if(!local.pending){
        const view=getDossier();
        savePending({dossierId:local.id,input:{selection:local.current.selection,
          expectedEditionSha256:local.current.editionSha256,questionId:$('document-question').value,
          label:$('document-label').value,expectedRevision:view.revision}});
      }
      const original=local.pending;
      const result=await api(endpoint('/receive'),{method:'POST',body:original.input});
      if(local.pending===original)savePending(null);
      await onReceived(result.dossier);await loadList();await open({editionId:result.editionId});
      notify((result.reused?'Recovered the original receiving result':'Document retained')+
        ' in dossier revision '+result.dossier.revision+'.');
    },event.currentTarget);
  });
  $('document-discard-pending').addEventListener('click',()=>withAction(async()=>{
    await loadList();savePending(null);
    if(local.current)$('document-label').value=local.current.retained?.label||
      (local.current.document.filename+' · '+local.current.binding.profileId).slice(0,240);
    renderQuestions();renderCurrent();
  }));
  root.querySelectorAll('[data-document-download]').forEach(button=>button.addEventListener('click',()=>withAction(async()=>{
    const value=local.current,response=await api(endpoint('/download'),{method:'POST',download:true,
      body:{selection:value.selection,expectedEditionSha256:value.editionSha256,file:button.dataset.documentDownload}});
    const blob=await response.blob(),url=URL.createObjectURL(blob),link=element('a');
    link.href=url;const match=/filename="([^"]+)"/.exec(response.headers.get('content-disposition')||'');
    link.download=match?.[1]||value.document.filename;document.body.append(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
  })));
  return {
    configure(value){local.configured=value?.configured===true;local.workspaceId=value?.workspaceId??null;tab.hidden=false;},
    setDossier(view){
      if(view?.id!==local.id){local.id=view?.id??null;local.version++;local.purchases=[];local.editions=[];
        local.current=null;local.records=null;local.next=null;local.offset=0;restorePending();renderList();renderCurrent();}
      renderQuestions();renderCurrent();
    },
    show(visible){const changed=visible!==local.shown;local.shown=visible;
      if(visible&&changed&&local.id)refresh().catch(error=>notify(friendly(error),'error'));},
    updateBusy(){renderCurrent();}
  };
}

// MIT. Managed document processing in the original research dossier workspace.
export function createUnstructuredPipelinesPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  const array=value=>Array.isArray(value)?value:[];
